#!/usr/bin/env python3
"""Render the portable English task page. Reproduction does not need this script."""
from pathlib import Path
import html
import markdown
ROOT=Path(__file__).resolve().parent
CSS='''*{box-sizing:border-box}body{margin:0;background:#f5f7f4;color:#19372e;font-family:system-ui,-apple-system,sans-serif;line-height:1.65}main{max-width:920px;margin:auto;padding:32px 24px}h1{font-size:32px;line-height:1.2}h2{font-size:22px}h3{font-size:17px}a{color:#176e5c}section,details{background:white;border:1px solid #d6e1da;border-radius:12px;padding:18px 22px;margin:16px 0}summary{font-weight:650;cursor:pointer}.lead{background:#eaf3ec;padding:16px 20px;border-left:4px solid #438870}.meta{color:#586d62;font-size:14px}nav,.flow{display:flex;gap:12px;flex-wrap:wrap}.flow span{background:#eaf0eb;padding:7px 12px;border-radius:8px}code{overflow-wrap:anywhere;background:#edf2ee;padding:2px 4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf2ee;padding:14px;border-radius:8px}pre code{padding:0}li{margin:6px 0}footer{color:#586d62;font-size:13px;margin-top:24px}@media(max-width:600px){main{padding:22px 15px}section,details{padding:15px}h1{font-size:26px}}'''
def md(s): return markdown.markdown(s,extensions=['fenced_code','sane_lists'])
body='''<h1>MicroDuck: build one continuous fetch</h1>
<p class="lead">Call “Mochi” → look at the caller → understand the orange-ball request → approach while watching → pick and rise → carry back to <strong>the same person</strong> → wait for them to take it.</p>
<p>Five people, five claimable tasks. Pick a small increment that fits your availability; tasks can be shared or handed over. Open a card for its concrete starting command, implementation steps and acceptance.</p>
<nav><a href="starter/README.md">Start locally</a><a href="CONTRACT.md">Shared interfaces</a><a href="ACCEPTANCE.md">Independent acceptance</a><a href="#discord">Discord message</a></nav>
<section><h2>What is ready</h2><p>A/B/E software and C/D historical CPU replay can start now. The package includes four policy exports, actual saved trace slices, detector/images, source references and a composed rehearsal. No robot, paid account or private credentials are required for the first checks.</p><p>Training for the changed body waits for F0: the new scan, measured masses and matched model. The assistant prepares the common files; Shawn supplies physical observations. New-body control and complete fetching are <strong>future acceptance gates</strong>.</p><div class="flow"><span>F0: match body</span><span>C + B: approach</span><span>D: pick → loaded exit</span><span>C + B + E: return → take</span></div><p>A develops alongside this path. D can start with measured stable entries from the baseline; B uses a configurable entry profile; C adds payload after D publishes its exit. Final handoffs run continuously without resetting the robot.</p></section>'''
for p in sorted((ROOT/'tasks').glob('*.md')):
 lines=p.read_text().splitlines(); title=lines[0][2:]
 body+=f'<details id="{p.name[0]}"><summary>{html.escape(title)}</summary>'+md('\n'.join(lines[1:]))+'</details>'
body+='''<section><h2>One-week increments, conditional week-two integration</h2><p>At a 30-minute meeting, run the starter, look at known failures and claim work. Leave a runnable branch within two days. At the first-week checkpoint, show a reproducible improvement or a decision-changing comparison. In week two, join live sensors and motion only when the physical prerequisites pass. This is not a promise of complete autonomous fetching in two weeks.</p><p>Difficulty/newness ratings are project judgments, not academic originality. See <a href="README.md">the coordination plan</a> for handover and reduced-staff execution.</p></section>'''
body+='<details id="discord"><summary>Discord invitation — ready to copy, not sent</summary>'+md((ROOT/'DISCORD.md').read_text())+'</details>'
body+='<footer>Prepared 3 November 2026. Independent acceptance covers task clarity, supplied startup and the exercised motor-free contract. See the linked receipt for exact evidence and remaining physical gates.</footer>'
(ROOT/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MicroDuck — claimable fetch tasks</title><style>'+CSS+'</style></head><body><main>'+body+'</main></body></html>')
print(ROOT/'index.html')
